 ('98000000-0000-4000-8000-000000000001','98000000-0000-4000-8000-000000000002','98000000-0000-4000-8000-000000000004',2,'2026-09-01','America/Sao_Paulo','[{"weekday":1,"start":"00:00","end":"01:00"}]','[]','98000000-0000-4000-8000-000000000003');
SELECT set_config('app.tenant_id','98000000-0000-4000-8000-000000000001',true),set_config('app.actor_id','98000000-0000-4000-8000-000000000003',true),set_config('app.correlation_id','effective-shift-test',true);
DO $$DECLARE r record;before_versions bigint;before_commands bigint;BEGIN
 SELECT count(*) INTO before_versions FROM unit_shift_schedule_versions;SELECT count(*) INTO before_commands FROM unit_shift_schedule_commands;
 SELECT * INTO r FROM evaluate_unit_staff_shift('98000000-0000-4000-8000-000000000002','98000000-0000-4000-8000-000000000004','2026-08-17T10:59:59Z');IF r.state<>'OUTSIDE_SHIFT' THEN RAISE EXCEPTION 'SHIFT_START_MINUS_INVALID';END IF;
 SELECT * INTO r FROM evaluate_unit_staff_shift('98000000-0000-4000-8000-000000000002','98000000-0000-4000-8000-000000000004','2026-08-17T11:00:00Z');IF r.state<>'IN_SHIFT' OR r.schedule_version<>1 OR r.local_time<>'08:00:00' THEN RAISE EXCEPTION 'SHIFT_START_INVALID';END IF;
 SELECT * INTO r FROM evaluate_unit_staff_shift('98000000-0000-4000-8000-000000000002','98000000-0000-4000-8000-000000000004','2026-08-17T15:00:00Z');IF r.state<>'OUTSIDE_SHIFT' THEN RAISE EXCEPTION 'SHIFT_END_EXCLUSIVE_INVALID';END IF;
 SELECT * INTO r FROM evaluate_unit_staff_shift('98000000-0000-4000-8000-000000000002','98000000-0000-4000-8000-000000000004','2026-08-18T15:00:00Z');IF r.state<>'CLOSED' THEN RAISE EXCEPTION 'SHIFT_CLOSED_INVALID';END IF;
 SELECT * INTO r FROM evaluate_unit_staff_shift('98000000-0000-4000-8000-000000000002','98000000-0000-4000-8000-000000000004','2026-08-19T17:30:00Z');IF r.state<>'IN_SHIFT' THEN RAISE EXCEPTION 'SHIFT_REPLACE_INVALID';END IF;
 SELECT * INTO r FROM evaluate_unit_staff_shift('98000000-0000-4000-8000-000000000002','98000000-0000-4000-8000-000000000004','2026-08-16T12:00:00Z');IF r.state<>'NOT_EFFECTIVE' OR r.schedule_version IS NOT NULL THEN RAISE EXCEPTION 'SHIFT_NOT_EFFECTIVE_INVALID';END IF;
 SELECT * INTO r FROM evaluate_unit_staff_shift('98000000-0000-4000-8000-000000000002','98000000-0000-4000-8000-000000000006','2026-08-17T12:00:00Z');IF r.state<>'UNCONFIGURED' THEN RAISE EXCEPTION 'SHIFT_UNCONFIGURED_INVALID';END IF;
 IF before_versions<>(SELECT count(*) FROM unit_shift_schedule_versions) OR before_commands<>(SELECT count(*) FROM unit_shift_schedule_commands) THEN RAISE EXCEPTION 'SHIFT_EVALUATION_MUTATED_STATE';END IF;
END$$;
