DO $$BEGIN IF has_function_privilege('zap_pronto_app','evaluate_unit_staff_shift(uuid,uuid,timestamptz)','EXECUTE') OR has_function_privilege('zap_pronto_worker','evaluate_unit_staff_shift(uuid,uuid,timestamptz)','EXECUTE') OR NOT has_function_privilege('zap_pronto_api','evaluate_unit_staff_shift(uuid,uuid,timestamptz)','EXECUTE') THEN RAISE EXCEPTION 'SHIFT_EVALUATION_GRANT_INVALID';END IF;END$$;
